import numpy as np

def sample_acf(x, nlags):
    x = np.asarray(x, dtype=float)
    d = x - x.mean()           # deviations from the full-sample mean
    denom = np.sum(d * d)      # one denominator for every lag
    out = [1.0]                # lag 0
    for k in range(1, nlags + 1):
        out.append(np.sum(d[k:] * d[:-k]) / denom)
    return np.array(out)

