import numpy as np

def acf_band(n, z=1.96):
    return z / np.sqrt(n)

def lags_outside_band(x, nlags):
    r = sample_acf(x, nlags)
    b = acf_band(len(x))
    return [k for k in range(1, nlags + 1) if abs(r[k]) > b]
